import type {
  LanguageModelV2CallWarning,
  LanguageModelV2StreamPart,
} from '@ai-sdk/provider';
import {
  type ModelMessage,
  executeTool,
  generateId,
  getErrorMessage,
} from '@ai-sdk/provider-utils';
import type { Tracer } from '@opentelemetry/api';
import { assembleOperationName } from '../telemetry/assemble-operation-name';
import { getTelemetryMetadataAttributes } from '../telemetry/get-base-telemetry-attributes';
import { recordErrorOnSpan, recordSpan } from '../telemetry/record-span';
import { selectTelemetryAttributes } from '../telemetry/select-telemetry-attributes';
import type { TelemetrySettings } from '../telemetry/telemetry-settings';
import type {
  FinishReason,
  LanguageModelUsage,
  ProviderMetadata,
} from '../types';
import type { Source } from '../types/language-model';
import {
  type GeneratedFile,
  DefaultGeneratedFileWithType,
} from './generated-file';
import { isToolExecutionAllowedFinishReason } from './is-tool-execution-allowed-finish-reason';
import { parseToolCall } from './parse-tool-call';
import type { TypedToolCall } from './tool-call';
import type { ToolCallRepairFunction } from './tool-call-repair-function';
import type { TypedToolError } from './tool-error';
import type { TypedToolResult } from './tool-result';
import type { ToolSet } from './tool-set';

export type SingleRequestTextStreamPart<TOOLS extends ToolSet> =
  // Text blocks:
  | {
      type: 'text-start';
      providerMetadata?: ProviderMetadata;
      id: string;
    }
  | {
      type: 'text-delta';
      id: string;
      providerMetadata?: ProviderMetadata;
      delta: string;
    }
  | {
      type: 'text-end';
      providerMetadata?: ProviderMetadata;
      id: string;
    }

  // Reasoning blocks:
  | {
      type: 'reasoning-start';
      providerMetadata?: ProviderMetadata;
      id: string;
    }
  | {
      type: 'reasoning-delta';
      id: string;
      providerMetadata?: ProviderMetadata;
      delta: string;
    }
  | {
      type: 'reasoning-end';
      id: string;
      providerMetadata?: ProviderMetadata;
    }

  // Tool calls:
  | {
      type: 'tool-input-start';
      id: string;
      toolName: string;
      providerMetadata?: ProviderMetadata;
    }
  | {
      type: 'tool-input-delta';
      id: string;
      delta: string;
      providerMetadata?: ProviderMetadata;
    }
  | {
      type: 'tool-input-end';
      id: string;
      providerMetadata?: ProviderMetadata;
    }
  | ({ type: 'source' } & Source)
  | { type: 'file'; file: GeneratedFile } // different because of GeneratedFile object
  | ({ type: 'tool-call' } & TypedToolCall<TOOLS>)
  | ({ type: 'tool-result' } & TypedToolResult<TOOLS>)
  | ({ type: 'tool-error' } & TypedToolError<TOOLS>)
  | { type: 'file'; file: GeneratedFile } // different because of GeneratedFile object
  | { type: 'stream-start'; warnings: LanguageModelV2CallWarning[] }
  | {
      type: 'response-metadata';
      id?: string;
      timestamp?: Date;
      modelId?: string;
    }
  | {
      type: 'finish';
      finishReason: FinishReason;
      usage: LanguageModelUsage;
      providerMetadata?: ProviderMetadata;
    }
  | { type: 'error'; error: unknown }
  | { type: 'raw'; rawValue: unknown };

export function runToolsTransformation<TOOLS extends ToolSet>({
  tools,
  generatorStream,
  tracer,
  telemetry,
  system,
  messages,
  abortSignal,
  repairToolCall,
  experimental_context,
}: {
  tools: TOOLS | undefined;
  generatorStream: ReadableStream<LanguageModelV2StreamPart>;
  tracer: Tracer;
  telemetry: TelemetrySettings | undefined;
  system: string | undefined;
  messages: ModelMessage[];
  abortSignal: AbortSignal | undefined;
  repairToolCall: ToolCallRepairFunction<TOOLS> | undefined;
  experimental_context: unknown;
}): ReadableStream<SingleRequestTextStreamPart<TOOLS>> {
  // tool results stream
  let toolResultsStreamController: ReadableStreamDefaultController<
    SingleRequestTextStreamPart<TOOLS>
  > | null = null;
  let toolResultsStreamClosed = false;
  const toolResultsStream = new ReadableStream<
    SingleRequestTextStreamPart<TOOLS>
  >({
    start(controller) {
      toolResultsStreamController = controller;
    },
    cancel() {
      toolResultsStreamClosed = true;
    },
  });

  function enqueueToolResult(chunk: SingleRequestTextStreamPart<TOOLS>) {
    if (toolResultsStreamClosed) {
      return;
    }

    try {
      toolResultsStreamController!.enqueue(chunk);
    } catch {
      toolResultsStreamClosed = true;
    }
  }

  function closeToolResultsStream() {
    if (toolResultsStreamClosed) {
      return;
    }

    toolResultsStreamClosed = true;

    try {
      toolResultsStreamController!.close();
    } catch {
      // suppress errors when the stream has been closed
    }
  }

  // keep track of outstanding tool results for stream closing:
  const outstandingToolResults = new Set<string>();

  // delay tool execution until the terminal finish reason is known:
  const pendingToolCalls: TypedToolCall<TOOLS>[] = [];

  // keep track of tool inputs for provider-side tool results
  const toolInputs = new Map<string, unknown>();

  let canClose = false;
  let finishChunk:
    | (SingleRequestTextStreamPart<TOOLS> & { type: 'finish' })
    | undefined = undefined;

  function attemptClose() {
    // close the tool results controller if no more outstanding tool calls
    if (canClose && outstandingToolResults.size === 0) {
      // we delay sending the finish chunk until all tool results (incl. delayed ones)
      // are received to ensure that the frontend receives tool results before a message
      // finish event arrives.
      if (finishChunk != null) {
        enqueueToolResult(finishChunk);
      }

      closeToolResultsStream();
    }
  }

  function executePendingToolCall(toolCall: TypedToolCall<TOOLS>) {
    const tool = tools![toolCall.toolName];
    const toolExecutionId = generateId(); // use our own id to guarantee uniqueness
    outstandingToolResults.add(toolExecutionId);

    // Note: we don't await the tool execution here (by leaving out 'await' on recordSpan),
    // because tool calls should execute concurrently.
    recordSpan({
      name: 'ai.toolCall',
      attributes: selectTelemetryAttributes({
        telemetry,
        attributes: {
          ...assembleOperationName({
            operationId: 'ai.toolCall',
            telemetry,
          }),
          ...getTelemetryMetadataAttributes(telemetry),
          'ai.toolCall.name': toolCall.toolName,
          'ai.toolCall.id': toolCall.toolCallId,
          'ai.toolCall.args': {
            output: () => JSON.stringify(toolCall.input),
          },
        },
      }),
      tracer,
      fn: async span => {
        let output: unknown;

        try {
          const stream = executeTool({
            execute: tool.execute!.bind(tool),
            input: toolCall.input,
            options: {
              toolCallId: toolCall.toolCallId,
              messages,
              abortSignal,
              experimental_context,
            },
          });

          for await (const part of stream) {
            enqueueToolResult({
              ...toolCall,
              type: 'tool-result',
              output: part.output,
              ...(part.type === 'preliminary' && {
                preliminary: true,
              }),
            });

            if (part.type === 'final') {
              output = part.output;
            }
          }
        } catch (error) {
          recordErrorOnSpan(span, error);
          enqueueToolResult({
            ...toolCall,
            type: 'tool-error',
            error,
          } satisfies TypedToolError<TOOLS>);

          outstandingToolResults.delete(toolExecutionId);
          attemptClose();
          return;
        }

        outstandingToolResults.delete(toolExecutionId);
        attemptClose();

        // record telemetry
        try {
          span.setAttributes(
            selectTelemetryAttributes({
              telemetry,
              attributes: {
                'ai.toolCall.result': {
                  output: () => JSON.stringify(output),
                },
              },
            }),
          );
        } catch (ignored) {
          // JSON stringify might fail if the result is not serializable,
          // in which case we just ignore it. In the future we might want to
          // add an optional serialize method to the tool interface and warn
          // if the result is not serializable.
        }
      },
    });
  }

  // forward stream
  const forwardStream = new TransformStream<
    LanguageModelV2StreamPart,
    SingleRequestTextStreamPart<TOOLS>
  >({
    async transform(
      chunk: LanguageModelV2StreamPart,
      controller: TransformStreamDefaultController<
        SingleRequestTextStreamPart<TOOLS>
      >,
    ) {
      const chunkType = chunk.type;

      switch (chunkType) {
        // forward:
        case 'stream-start':
        case 'text-start':
        case 'text-delta':
        case 'text-end':
        case 'reasoning-start':
        case 'reasoning-delta':
        case 'reasoning-end':
        case 'tool-input-start':
        case 'tool-input-delta':
        case 'tool-input-end':
        case 'source':
        case 'response-metadata':
        case 'error':
        case 'raw': {
          controller.enqueue(chunk);
          break;
        }

        case 'file': {
          controller.enqueue({
            type: 'file',
            file: new DefaultGeneratedFileWithType({
              data: chunk.data,
              mediaType: chunk.mediaType,
            }),
          });
          break;
        }

        case 'finish': {
          finishChunk = {
            type: 'finish',
            finishReason: chunk.finishReason,
            usage: chunk.usage,
            providerMetadata: chunk.providerMetadata,
          };

          if (isToolExecutionAllowedFinishReason(chunk.finishReason)) {
            for (const toolCall of pendingToolCalls.splice(0)) {
              executePendingToolCall(toolCall);
            }
          } else {
            pendingToolCalls.length = 0;
          }

          break;
        }

        // process tool call:
        case 'tool-call': {
          try {
            const toolCall = await parseToolCall({
              toolCall: chunk,
              tools,
              repairToolCall,
              system,
              messages,
            });

            controller.enqueue(toolCall);

            // handle invalid tool calls:
            if (toolCall.invalid) {
              enqueueToolResult({
                type: 'tool-error',
                toolCallId: toolCall.toolCallId,
                toolName: toolCall.toolName,
                input: toolCall.input,
                error: getErrorMessage(toolCall.error!),
                dynamic: true,
              });

              break;
            }

            const tool = tools![toolCall.toolName];

            toolInputs.set(toolCall.toolCallId, toolCall.input);

            if (tool.onInputAvailable != null) {
              await tool.onInputAvailable({
                input: toolCall.input,
                toolCallId: toolCall.toolCallId,
                messages,
                abortSignal,
                experimental_context,
              });
            }

            // Only execute tools that are not provider-executed:
            if (tool.execute != null && toolCall.providerExecuted !== true) {
              pendingToolCalls.push({ ...toolCall });
            }
          } catch (error) {
            enqueueToolResult({ type: 'error', error });
          }

          break;
        }

        case 'tool-result': {
          const toolName = chunk.toolName as keyof TOOLS & string;

          if (chunk.isError) {
            enqueueToolResult({
              type: 'tool-error',
              toolCallId: chunk.toolCallId,
              toolName,
              input: toolInputs.get(chunk.toolCallId),
              providerExecuted: chunk.providerExecuted,
              error: chunk.result,
            } as TypedToolError<TOOLS>);
          } else {
            controller.enqueue({
              type: 'tool-result',
              toolCallId: chunk.toolCallId,
              toolName,
              input: toolInputs.get(chunk.toolCallId),
              output: chunk.result,
              providerExecuted: chunk.providerExecuted,
            } as TypedToolResult<TOOLS>);
          }
          break;
        }

        default: {
          const _exhaustiveCheck: never = chunkType;
          throw new Error(`Unhandled chunk type: ${_exhaustiveCheck}`);
        }
      }
    },

    flush() {
      canClose = true;
      attemptClose();
    },
  });

  // combine the generator stream and the tool results stream
  return new ReadableStream<SingleRequestTextStreamPart<TOOLS>>({
    async start(controller) {
      // need to wait for both pipes so there are no dangling promises that
      // can cause uncaught promise rejections when the stream is aborted
      return Promise.all([
        generatorStream.pipeThrough(forwardStream).pipeTo(
          new WritableStream({
            write(chunk) {
              controller.enqueue(chunk);
            },
            close() {
              // the generator stream controller is automatically closed when it's consumed
            },
          }),
        ),
        toolResultsStream.pipeTo(
          new WritableStream({
            write(chunk) {
              controller.enqueue(chunk);
            },
            close() {
              controller.close();
            },
          }),
        ),
      ]);
    },
  });
}
